package com.apptomo.v4.aireactechartdashboard.querydashboard.repository;
import com.apptomo.v4.aireactechartdashboard.querydashboard.dto.*; import lombok.RequiredArgsConstructor; import org.springframework.jdbc.core.namedparam.*; import org.springframework.stereotype.Repository; import java.sql.Timestamp; import java.time.LocalDateTime; import java.util.*;
// 20260928 추가
@Repository @RequiredArgsConstructor public class QueryAnalyticsRepository { private final NamedParameterJdbcTemplate jdbc;
 private static Double d(Object v){return v==null?null:((Number)v).doubleValue();} private static Long l(Object v){return v==null?null:((Number)v).longValue();} private static String s(Object v){return v==null?null:String.valueOf(v).replace(' ','T');}
 public QueryAnalyticsDto find(LocalDateTime st,LocalDateTime en,String host,String worker,int page,int size){MapSqlParameterSource p=new MapSqlParameterSource().addValue("st",Timestamp.valueOf(st)).addValue("en",Timestamp.valueOf(en)).addValue("host",host==null?"":host).addValue("worker",worker==null?"":worker).addValue("limit",size).addValue("offset",page*size);
 String where=" FROM public.ax_metrics_sqream_worker_log wl LEFT JOIN LATERAL (SELECT n.cpu_usage_percent,n.memory_usage_percent,n.disk_usage_percent FROM public.ax_metrics_node n WHERE n.hostname=wl.hostname AND n.collect_time BETWEEN wl.query_start_time-interval '5 minutes' AND wl.query_end_time+interval '5 minutes' ORDER BY n.collect_time DESC LIMIT 1) nm ON true LEFT JOIN LATERAL (SELECT MAX(d.gr_engine_active_percent*100.0) gpu FROM public.ax_metrics_gpu_dcgmi_metric d JOIN public.ax_metrics_gpu_nvidia_smi_info ni ON ni.id=d.nvidia_smi_id WHERE ni.hostname=wl.hostname AND d.snapshot_time BETWEEN wl.query_start_time-interval '5 minutes' AND wl.query_end_time+interval '5 minutes') gm ON true WHERE wl.query_start_time>=CAST(:st AS timestamp) AND wl.query_end_time<=CAST(:en AS timestamp) AND (CAST(:host AS varchar)='' OR wl.hostname=CAST(:host AS varchar)) AND (CAST(:worker AS varchar)='' OR wl.worker_hostname=CAST(:worker AS varchar)) ";
 QueryAnalyticsDto o=new QueryAnalyticsDto(); Map<String,Object> k=jdbc.queryForMap("SELECT COUNT(*) cnt,MAX(COALESCE(gm.gpu,0)) gpu,MAX(COALESCE(nm.cpu_usage_percent,0)) cpu,COUNT(*) FILTER(WHERE COALESCE(gm.gpu,0)>=80) heavy,AVG(wl.query_execution_time_ms)/1000.0 avgsec"+where,p); o.totalQueries=((Number)k.get("cnt")).longValue();o.totalElements=o.totalQueries;o.gpuUsageMax=d(k.get("gpu"));o.cpuUsageMax=d(k.get("cpu"));o.heavyQueries=((Number)k.get("heavy")).longValue();o.avgDurationSec=d(k.get("avgsec"));o.page=page;o.size=size;o.totalPages=(int)Math.ceil(o.totalElements/(double)size);
 String rows="SELECT wl.hostname,wl.worker_hostname,wl.service_name,wl.database_name,wl.sql_type,wl.user_id,wl.statement,wl.query_start_time,wl.query_end_time,wl.connection_id,wl.statement_id,wl.query_execution_time_ms,wl.total_data_read_mb,wl.total_processed_rows,wl.result_row_count,nm.cpu_usage_percent,nm.memory_usage_percent,nm.disk_usage_percent,gm.gpu"+where+" ORDER BY wl.query_start_time DESC LIMIT :limit OFFSET :offset";
 for(Map<String,Object> r:jdbc.queryForList(rows,p)){QueryRowDto q=new QueryRowDto();q.hostname=s(r.get("hostname"));q.worker=s(r.get("worker_hostname"));q.serviceName=s(r.get("service_name"));q.databaseName=s(r.get("database_name"));q.sqlType=s(r.get("sql_type"));q.userId=s(r.get("user_id"));q.statement=s(r.get("statement"));q.queryStart=s(r.get("query_start_time"));q.queryEnd=s(r.get("query_end_time"));q.connectionId=l(r.get("connection_id"));q.statementId=l(r.get("statement_id"));q.durationMs=l(r.get("query_execution_time_ms"));q.totalDataReadMb=d(r.get("total_data_read_mb"));q.totalProcessedRows=l(r.get("total_processed_rows"));q.resultRowCount=l(r.get("result_row_count"));q.cpuUsagePercent=d(r.get("cpu_usage_percent"));q.gpuUsagePercent=d(r.get("gpu"));q.memoryUsagePercent=d(r.get("memory_usage_percent"));q.diskUsagePercent=d(r.get("disk_usage_percent"));o.queries.add(q);}
 String grp="SELECT COALESCE(wl.sql_type,'UNKNOWN') sql_type,COALESCE(wl.database_name,'UNKNOWN') database_name,COUNT(*) cnt,AVG(wl.query_execution_time_ms)/1000.0 avgsec,MAX(COALESCE(gm.gpu,0)) gpu,MAX(COALESCE(nm.cpu_usage_percent,0)) cpu,AVG(nm.memory_usage_percent) mem,AVG(nm.disk_usage_percent) disk,SUM(COALESCE(wl.total_data_read_mb,0)) readmb"+where+" GROUP BY wl.sql_type,wl.database_name ORDER BY cnt DESC,sql_type,database_name";
 for(Map<String,Object> r:jdbc.queryForList(grp,p)){QueryGroupDto g=new QueryGroupDto();g.sqlType=s(r.get("sql_type"));g.databaseName=s(r.get("database_name"));g.queryCount=((Number)r.get("cnt")).longValue();g.avgDurationSec=d(r.get("avgsec"));g.maxGpuUsagePercent=d(r.get("gpu"));g.maxCpuUsagePercent=d(r.get("cpu"));g.avgMemoryUsagePercent=d(r.get("mem"));g.avgDiskUsagePercent=d(r.get("disk"));g.totalDataReadMb=d(r.get("readmb"));o.groups.add(g);}return o; }

 // 20260928 추가 : ax_metrics_sqream_worker_log 기반 /logs 전체 목록/페이징
 public LogMonitoringDto findLogs(LocalDateTime st,LocalDateTime en,String host,String worker,String level,String search,int page,int size){
  MapSqlParameterSource p=new MapSqlParameterSource().addValue("st",Timestamp.valueOf(st)).addValue("en",Timestamp.valueOf(en)).addValue("host",host==null?"":host).addValue("worker",worker==null?"":worker).addValue("level",level==null?"":level.toUpperCase()).addValue("search",search==null?"":search).addValue("limit",size).addValue("offset",page*size);
  String levelExpr="CASE WHEN CAST(wl.message_type_id AS varchar) IN ('20','21','500','1010') OR UPPER(COALESCE(wl.information_level,'')) LIKE '%ERROR%' THEN 'ERROR' WHEN UPPER(COALESCE(wl.information_level,'')) LIKE '%WARN%' THEN 'WARNING' ELSE 'INFO' END";
  String where=" FROM public.ax_metrics_sqream_worker_log wl WHERE COALESCE(wl.query_end_time,wl.collect_time)>=CAST(:st AS timestamp) AND COALESCE(wl.query_end_time,wl.collect_time)<=CAST(:en AS timestamp) AND (CAST(:host AS varchar)='' OR wl.hostname=CAST(:host AS varchar)) AND (CAST(:worker AS varchar)='' OR wl.worker_hostname=CAST(:worker AS varchar)) AND (CAST(:level AS varchar)='' OR "+levelExpr+"=CAST(:level AS varchar)) AND (CAST(:search AS varchar)='' OR COALESCE(wl.message,'') ILIKE '%'||CAST(:search AS varchar)||'%' OR COALESCE(wl.hostname,'') ILIKE '%'||CAST(:search AS varchar)||'%' OR COALESCE(wl.worker_hostname,'') ILIKE '%'||CAST(:search AS varchar)||'%') ";
  LogMonitoringDto o=new LogMonitoringDto();
  Map<String,Object> k=jdbc.queryForMap("SELECT COUNT(*) cnt,COUNT(*) FILTER(WHERE "+levelExpr+"='ERROR') errors,COUNT(*) FILTER(WHERE "+levelExpr+"='WARNING') warnings,COUNT(*) FILTER(WHERE "+levelExpr+"='INFO') info"+where,p);
  o.totalEntries=((Number)k.get("cnt")).longValue(); o.errors=((Number)k.get("errors")).longValue(); o.warnings=((Number)k.get("warnings")).longValue(); o.info=((Number)k.get("info")).longValue(); o.totalElements=o.totalEntries; o.page=page;o.size=size;o.totalPages=(int)Math.ceil(o.totalElements/(double)size);
  // 20260928 추가 - 조회 구간을 30개 버킷으로 나눠 ERROR/WARNING/INFO 시간대별 꺾은선 데이터 생성
  String distSql="SELECT date_bin(GREATEST((EXTRACT(EPOCH FROM (CAST(:en AS timestamp)-CAST(:st AS timestamp)))/30)::int,1) * interval '1 second', COALESCE(wl.query_end_time,wl.collect_time), CAST(:st AS timestamp)) bucket,"+
      " COUNT(*) FILTER(WHERE "+levelExpr+"='ERROR') errors,"+
      " COUNT(*) FILTER(WHERE "+levelExpr+"='WARNING') warnings,"+
      " COUNT(*) FILTER(WHERE "+levelExpr+"='INFO') info"+where+" GROUP BY bucket ORDER BY bucket";
  for(Map<String,Object> r:jdbc.queryForList(distSql,p)){LogDistributionPointDto x=new LogDistributionPointDto();x.time=s(r.get("bucket"));x.errors=((Number)r.get("errors")).longValue();x.warnings=((Number)r.get("warnings")).longValue();x.info=((Number)r.get("info")).longValue();o.distribution.add(x);}
  String sql="SELECT COALESCE(wl.query_end_time,wl.collect_time) event_time,wl.hostname,wl.worker_hostname,"+levelExpr+" level,wl.message_type_id,wl.message,wl.statement_id,wl.connection_id"+where+" ORDER BY CASE "+levelExpr+" WHEN 'ERROR' THEN 0 WHEN 'WARNING' THEN 1 ELSE 2 END, COALESCE(wl.query_end_time,wl.collect_time) DESC LIMIT :limit OFFSET :offset";
  for(Map<String,Object> r:jdbc.queryForList(sql,p)){LogRowDto d=new LogRowDto();d.timestamp=s(r.get("event_time"));d.hostname=s(r.get("hostname"));d.worker=s(r.get("worker_hostname"));d.level=s(r.get("level"));d.messageTypeId=r.get("message_type_id")==null?null:((Number)r.get("message_type_id")).intValue();d.message=s(r.get("message"));d.statementId=l(r.get("statement_id"));d.connectionId=l(r.get("connection_id"));o.logs.add(d);}
  return o;
 }

 // 20260928 추가 : SQL Type / Database Summary 선택 상세
 public QueryGroupDetailDto findGroupDetail(LocalDateTime st,LocalDateTime en,String sqlType,String databaseName,String host,String worker){
  MapSqlParameterSource p=new MapSqlParameterSource()
      .addValue("st",Timestamp.valueOf(st)).addValue("en",Timestamp.valueOf(en))
      .addValue("sqlType",sqlType).addValue("databaseName",databaseName)
      .addValue("host",host==null?"":host).addValue("worker",worker==null?"":worker);
  String qWhere=" FROM public.ax_metrics_sqream_worker_log wl WHERE wl.query_start_time>=CAST(:st AS timestamp) AND wl.query_end_time<=CAST(:en AS timestamp)"+
      " AND COALESCE(wl.sql_type,'UNKNOWN')=CAST(:sqlType AS varchar) AND COALESCE(wl.database_name,'UNKNOWN')=CAST(:databaseName AS varchar)"+
      " AND (CAST(:host AS varchar)='' OR wl.hostname=CAST(:host AS varchar)) AND (CAST(:worker AS varchar)='' OR wl.worker_hostname=CAST(:worker AS varchar)) ";
  QueryGroupDetailDto o=new QueryGroupDetailDto(); o.sqlType=sqlType;o.databaseName=databaseName;
  String qSql="SELECT wl.hostname,wl.worker_hostname,wl.service_name,wl.database_name,wl.sql_type,wl.user_id,wl.statement,wl.query_start_time,wl.query_end_time,wl.connection_id,wl.statement_id,wl.query_execution_time_ms,wl.total_data_read_mb,wl.total_processed_rows,wl.result_row_count"+qWhere+" ORDER BY wl.query_start_time ASC LIMIT 200";
  List<Map<String,Object>> qr=jdbc.queryForList(qSql,p);
  LocalDateTime min=null,max=null;
  Set<String> hosts=new LinkedHashSet<>();
  for(Map<String,Object> r:qr){
   QueryRowDto q=new QueryRowDto();q.hostname=s(r.get("hostname"));q.worker=s(r.get("worker_hostname"));q.serviceName=s(r.get("service_name"));q.databaseName=s(r.get("database_name"));q.sqlType=s(r.get("sql_type"));q.userId=s(r.get("user_id"));q.statement=s(r.get("statement"));q.queryStart=s(r.get("query_start_time"));q.queryEnd=s(r.get("query_end_time"));q.connectionId=l(r.get("connection_id"));q.statementId=l(r.get("statement_id"));q.durationMs=l(r.get("query_execution_time_ms"));q.totalDataReadMb=d(r.get("total_data_read_mb"));q.totalProcessedRows=l(r.get("total_processed_rows"));q.resultRowCount=l(r.get("result_row_count"));o.queries.add(q);
   Object a=r.get("query_start_time"),b=r.get("query_end_time"); if(a instanceof Timestamp){LocalDateTime x=((Timestamp)a).toLocalDateTime();if(min==null||x.isBefore(min))min=x;} if(b instanceof Timestamp){LocalDateTime x=((Timestamp)b).toLocalDateTime();if(max==null||x.isAfter(max))max=x;} if(r.get("hostname")!=null)hosts.add(String.valueOf(r.get("hostname")));
  }
  if(min==null||max==null)return o;
  // 수집 텀이 Query 경계와 정확히 일치하지 않을 수 있으므로 앞뒤 60초 확보
  LocalDateTime rs=min.minusSeconds(60), re=max.plusSeconds(60); o.resourceStart=rs.toString();o.resourceEnd=re.toString();
  p.addValue("rs",Timestamp.valueOf(rs)).addValue("re",Timestamp.valueOf(re)).addValue("hosts",String.join(",",hosts));
  // 20260928 추가 : node.collect_time을 기준축으로 하고 같은 hostname GPU는 가장 가까운 snapshot_time(±30초)을 평균
  String resourceSql="SELECT n.collect_time,AVG(n.cpu_usage_percent) cpu,AVG(n.memory_usage_percent) mem,AVG(n.disk_usage_percent) disk,"+
      " AVG(g.gpu) gpu FROM public.ax_metrics_node n LEFT JOIN LATERAL (SELECT AVG(CASE WHEN d.gr_engine_active_percent<=1 THEN d.gr_engine_active_percent*100.0 ELSE d.gr_engine_active_percent END) gpu FROM public.ax_metrics_gpu_nvidia_smi_info ni JOIN public.ax_metrics_gpu_dcgmi_metric d ON d.nvidia_smi_id=ni.id WHERE ni.hostname=n.hostname AND d.snapshot_time BETWEEN n.collect_time-interval '30 seconds' AND n.collect_time+interval '30 seconds') g ON true"+
      " WHERE n.collect_time BETWEEN CAST(:rs AS timestamp) AND CAST(:re AS timestamp) AND (CAST(:hosts AS varchar)='' OR n.hostname=ANY(string_to_array(CAST(:hosts AS varchar),','))) GROUP BY n.collect_time ORDER BY n.collect_time";
  for(Map<String,Object> r:jdbc.queryForList(resourceSql,p)){QueryResourcePointDto x=new QueryResourcePointDto();x.collectTime=s(r.get("collect_time"));x.cpuUsagePercent=d(r.get("cpu"));x.memoryUsagePercent=d(r.get("mem"));x.diskUsagePercent=d(r.get("disk"));x.gpuUsagePercent=d(r.get("gpu"));o.resources.add(x);}
  return o;
 }
}
